document.addEventListener("DOMContentLoaded",loadPublicMenu);function _menuMondayOf(e){const t=e.getDay(),n=t===0?-6:1-t,a=new Date(e);return a.setDate(e.getDate()+n),a.toISOString().split("T")[0]}function _menuWeekdayDates(e){const t=new Date(e+"T00:00:00"),n=[];for(let a=0;a<7;a++){const s=new Date(t);s.setDate(t.getDate()+a);const l=s.getDay();l===0||l===6||n.push(s.toISOString().split("T")[0])}return n}function _menuDayLabel(e){return new Date(e+"T00:00:00").toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"})}async function loadPublicMenu(){const e=document.getElementById("menuContent");if(!sbClient){e.innerHTML='<p class="empty-hint">Menu unavailable right now \u2014 please check back later.</p>';return}const t=_menuMondayOf(new Date),n=new Date(t+"T00:00:00");n.setDate(n.getDate()+7);const a=n.toISOString().split("T")[0],s=[{label:"This Week",dates:_menuWeekdayDates(t)},{label:"Next Week",dates:_menuWeekdayDates(a)}],l=[...s[0].dates,...s[1].dates],{data:i,error:u}=await sbClient.from("cacfp_menus").select("menu_date, meal_type, food_items, milk, meat_alt, vegetable, fruit, grain").in("menu_date",l).eq("status","published").order("menu_date");if(u){console.error("loadPublicMenu:",u),e.innerHTML='<p class="empty-hint">Menu unavailable right now \u2014 please check back later.</p>';return}if(!i||!i.length){e.innerHTML='<p class="empty-hint">No menu has been posted yet \u2014 please check back soon.</p>';return}const h=s.map(m=>{const r=m.dates.filter(o=>i.some(c=>c.menu_date===o));return r.length?`
            <h2>${m.label}</h2>
            <div class="menu-grid-wrap">
            <table class="menu-table">
                <thead><tr><th>Meal</th>${r.map(o=>`<th>${_menuDayLabel(o)}</th>`).join("")}</tr></thead>
                <tbody>
                    ${CACFP_MEAL_TYPES.map(o=>`
                        <tr>
                            <td><strong>${o.label}</strong></td>
                            ${r.map(c=>{const d=i.find(p=>p.menu_date===c&&p.meal_type===o.id);return`<td>${d&&d.food_items?escHtml(d.food_items):"\u2014"}</td>`}).join("")}
                        </tr>
                    `).join("")}
                </tbody>
            </table>
            </div>`:""}).join("");e.innerHTML=h||'<p class="empty-hint">No menu has been posted yet \u2014 please check back soon.</p>'}
